import re
lines = open('answer.md').read().split('\n')
tables=[]; cur=[]
for i,l in enumerate(lines):
    if l.startswith('|'):
        cur.append((i+1,l))
    else:
        if cur: tables.append(cur); cur=[]
if cur: tables.append(cur)
for t in tables:
    counts = [len(re.split(r'(?<!\\)\|', l))-2 for _,l in t]
    status = 'OK' if len(set(counts))==1 else 'MISMATCH'
    print(t[0][0], status, counts[:3], '...', len(t), 'rows')
EOF
